key_patterns.property_decorator:
@property
def value(self) -> Type:
    return self._value

@value.setter
def value(self, val: Type) -> None:
    self._value = val

key_patterns.dataclass:
from dataclasses import dataclass, field

@dataclass
class MyClass:
    name: str
    value: int = 0
    items: list = field(default_factory=list)
